const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');

const app = express();

// Security Middleware
app.use(helmet()); // Sets secure HTTP headers
app.use(helmet.hidePoweredBy());

// Logging
if (process.env.NODE_ENV !== 'test') {
  app.use(morgan('dev'));
}

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests from this IP, please try again later.' },
  standardHeaders: true, // return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // disable X-RateLimit-* headers
});

// Apply rate limiting to all routes
app.use(limiter);

// Parse JSON with size limit to prevent flooding
app.use(express.json({ limit: '10kb' }));

// Health check - public
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Simulated user data
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// GET /users - list all users
app.get('/users', (req, res, next) => {
  try {
    // Simulate possible async/error scenario
    if (!users) {
      const error = new Error('User data temporarily unavailable');
      error.status = 500;
      return next(error);
    }
    res.json(users);
  } catch (err) {
    next(err);
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err.stack); // Log error (in prod, use a proper logger)
  const status = err.status || 500;
  res.status(status).json({
    error: 'Something went wrong!',
    message: process.env.NODE_ENV === 'development' ? err.message : undefined,
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received: Shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

