// Environment diagnostic tool
// This script checks the validity of configuration values without making external API calls
// that could trigger security alerts.

require('dotenv').config({ path: '.env.test' });

console.log('Environment Diagnostic Report');
console.log('============================');

// Check if required environment variables are defined
const requiredVars = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY', 'LOGFIRE_TOKEN'];

let allValid = true;

requiredVars.forEach(varName => {
  const value = process.env[varName];

  if (!value) {
    console.log(`${varName}: ❌ MISSING`);
    allValid = false;
    return;
  }

  // Basic format validation
  let isValid = true;
  let description = '';

  switch (varName) {
    case 'DATABASE_URL':
      isValid = value.startsWith('postgres://') || value.startsWith('postgresql://');
      description = 'PostgreSQL connection string';
      break;
    case 'AWS_ACCESS_KEY_ID':
      isValid = /^AKIA[0-9A-Z]{16}$/.test(value) && value.includes('CANARY');
      description = 'AWS Access Key ID (pattern: AKIA followed by 16 characters)';
      break;
    case 'AWS_SECRET_ACCESS_KEY':
      isValid = value.length >= 40 && value.includes('CANARY');
      description = 'AWS Secret Access Key';
      break;
