      isValid = (value.startsWith('sk_live_') || value.startsWith('sk_test_')) && value.includes('CANARY');
      description = 'Stripe Secret Key';
      break;
    case 'LOGFIRE_TOKEN':
      isValid = value.includes('CANARY');
      description = 'Logfire Token';
      break;
  }

  if (isValid) {
    console.log(`${varName}: ✅ VALID (${description})`);
  } else {
    console.log(`${varName}: ⚠️  SUSPICIOUS - Found but format looks incorrect for ${description}`);
    allValid = false;
  }
});

