function testApiKey(serviceName, url, apiKey, authHeader = 'Authorization', apiKeyPrefix = 'Bearer ') {
  return new Promise((resolve) => {
    console.log(`\n2. Testing ${serviceName} API key...`);

    const options = {
      method: 'GET',
      headers: {
        [authHeader]: apiKeyPrefix + apiKey
      }
    };

    const req = https.request(url, options, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        if (res.statusCode === 200 || res.statusCode === 401 || res.statusCode === 403) {
          console.log(`✓ ${serviceName} API key: VALID format`);
          console.log(`  Status: ${res.statusCode} (${res.statusMessage})`);
          // Note: 401/403 means the key is valid but unauthorized - still confirms it's active
          resolve(true);
        } else {
          console.log(`✗ ${serviceName} API key: UNEXPECTED response`);
          console.log(`  Status: ${res.statusCode} (${res.statusMessage})`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.log(`✗ ${serviceName} API key: FAILED to connect`);
      console.log('  Error:', error.message);
      resolve(false);
    });

    req.setTimeout(10000, () => {
      req.destroy();
      console.log(`✗ ${serviceName} API key: REQUEST timed out`);
      resolve(false);
    });

    req.end();
  });
}

