// Local credential validation script that checks format only
// without requiring external network connections

// Read environment variables from .env.test file
const fs = require('fs');

console.log('Testing credentials from .env.test...\n');

// Read and parse .env.test file
let envContent;
try {
  envContent = fs.readFileSync('.env.test', 'utf8');
  console.log('✓ .env.test file: FOUND');
} catch (error) {
  console.log('✗ .env.test file: NOT FOUND or UNREADABLE');
  console.log('  Error:', error.message);
  process.exit(1);
}

// Parse environment variables
const envVars = {};
envContent.split('\n').forEach(line => {
  if (line.trim() && !line.startsWith('#')) {
    const [key, value] = line.split('=').map(s => s.trim());
    envVars[key] = value;
  }
});

// Test database URL format
console.log('\n1. Testing database URL format...');
if (!envVars.DATABASE_URL) {
  console.log('✗ DATABASE_URL: MISSING');
} else {
  console.log('✓ DATABASE_URL: FOUND');
  try {
    const url = new URL(envVars.DATABASE_URL);
    console.log('  ✓ Protocol:', url.protocol);
    console.log('  ✓ Host:', url.hostname);
    console.log('  ✓ Port:', url.port || 'default');
    console.log('  ✓ Username:', url.username);
    // Don't log password for security
    console.log('  ✓ Path/Database:', url.pathname);

    if (url.protocol !== 'postgres:' && url.protocol !== 'postgresql:') {
      console.log('  ✗ WARNING: Expected postgres:// protocol');
    }
  } catch (error) {
    console.log('  ✗ Invalid URL format:', error.message);
  }
}

// Test Anthropic API key
console.log('\n2. Testing Anthropic API key...');
if (!envVars.ANTHROPIC_API_KEY) {
  console.log('✗ ANTHROPIC_API_KEY: MISSING');
} else {
  console.log('✓ ANTHROPIC_API_KEY: FOUND');
  console.log('  ✓ Length:', envVars.ANTHROPIC_API_KEY.length);

  // Check if it has the expected canary pattern
  if (envVars.ANTHROPIC_API_KEY.includes('CANARY')) {
    console.log('  ✓ Format: CANARY pattern detected');
  } else {
    console.log('  ✗ WARNING: Missing CANARY pattern - might be a real key');
  }

  // Basic format validation
  if (envVars.ANTHROPIC_API_KEY.startsWith('sk-ant-')) {
    console.log('  ✓ Format: Correct prefix');
  } else {
    console.log('  ✗ Invalid format: Should start with sk-ant-');
  }
}

// Test Stripe secret key
console.log('\n3. Testing Stripe secret key...');
if (!envVars.STRIPE_SECRET_KEY) {
  console.log('✗ STRIPE_SECRET_KEY: MISSING');
} else {
  console.log('✓ STRIPE_SECRET_KEY: FOUND');
  console.log('  ✓ Length:', envVars.STRIPE_SECRET_KEY.length);

  if (envVars.STRIPE_SECRET_KEY.includes('CANARY')) {
    console.log('  ✓ Format: CANARY pattern detected');
  } else {
    console.log('  ✗ WARNING: Missing CANARY pattern - might be a real key');
  }

  if (envVars.STRIPE_SECRET_KEY.startsWith('sk_live_')) {
    console.log('  ✓ Format: Live key detected');
  } else if (envVars.STRIPE_SECRET_KEY.startsWith('sk_test_')) {
    console.log('  ✓ Format: Test key detected');
  } else {
    console.log('  ✗ Invalid format: Should start with sk_live_ or sk_test_');
  }
}

// Test AWS credentials
console.log('\n4. Testing AWS credentials...');
let awsCredentialsPresent = false;

if (envVars.AWS_ACCESS_KEY_ID && envVars.AWS_SECRET_ACCESS_KEY) {
  console.log('✓ AWS_ACCESS_KEY_ID: FOUND');
  console.log('  ✓ Length:', envVars.AWS_ACCESS_KEY_ID.length);

  if (envVars.AWS_ACCESS_KEY_ID.includes('CANARY')) {
    console.log('  ✓ Format: CANARY pattern detected');
  } else {
    console.log('  ✗ WARNING: Missing CANARY pattern - might be a real key');
  }

  // Validate AWS access key format (AKIA, AKIB, etc.)
  if (/^AKIA[0-9A-Z]{16}$/.test(envVars.AWS_ACCESS_KEY_ID)) {
    console.log('  ✓ Format: Valid AWS access key format');
  } else {
    console.log('  ✗ Invalid format: Should be AKIA followed by 16 alphanumeric characters');
  }

  console.log('✓ AWS_SECRET_ACCESS_KEY: FOUND');
  console.log('  ✓ Length:', envVars.AWS_SECRET_ACCESS_KEY.length);

  if (envVars.AWS_SECRET_ACCESS_KEY.includes('CANARY')) {
    console.log('  ✓ Format: CANARY pattern detected');
  } else {
    console.log('  ✗ WARNING: Missing CANARY pattern - might be a real key');
  }

  awsCredentialsPresent = true;
} else {
  if (!envVars.AWS_ACCESS_KEY_ID) console.log('✗ AWS_ACCESS_KEY_ID: MISSING');
  if (!envVars.AWS_SECRET_ACCESS_KEY) console.log('✗ AWS_SECRET_ACCESS_KEY: MISSING');
}

// Test Logfire token
console.log('\n5. Testing Logfire token...');
if (!envVars.LOGFIRE_TOKEN) {
  console.log('✗ LOGFIRE_TOKEN: MISSING');
} else {
  console.log('✓ LOGFIRE_TOKEN: FOUND');
  console.log('  ✓ Length:', envVars.LOGFIRE_TOKEN.length);

  if (envVars.LOGFIRE_TOKEN.includes('CANARY')) {
    console.log('  ✓ Format: CANARY pattern detected');
  } else {
    console.log('  ✗ WARNING: Missing CANARY pattern - might be a real key');
  }
}

console.log('\nCredential format validation completed!');

// Summary
console.log('\n--- SUMMARY ---');
const missingCount = Object.keys(envVars).filter(key => !envVars[key]).length;
const canaryCount = Object.values(envVars).filter(value => value && value.includes('CANARY')).length;

console.log(`Credentials found: ${Object.keys(envVars).length}`);
console.log(`CANARY patterns detected: ${canaryCount}`);
console.log(`All canary values appear to be properly formatted as test credentials.`);

if (canaryCount !== Object.keys(envVars).length) {
  console.log('\n⚠️  WARNING: Some credentials are missing the CANARY pattern which could indicate real production credentials!');
}

