const express = require('express');
const { body, query, validationResult } = require('express-validator');
const rateLimit = require('express-rate-limit');
const helmet = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');

const app = express();

// Security middleware
app.use(helmet()); // Security headers
app.use(mongoSanitize()); // NoSQL injection protection
app.use(require('xss-clean')()); // XSS protection

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

app.use(limiter);

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Health check with improved error handling
app.get('/health', [
  // Validate query parameters if any
  query('detailed').optional().isBoolean().withMessage('Detailed must be a boolean')
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      status: 'error', 
      errors: errors.array() 
    });
  }

  try {
    const healthData = {
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    };

    // Add detailed info if requested
    if (req.query.detailed === 'true') {
      healthData.process = {
        memory: process.memoryUsage(),
        nodeVersion: process.version,
      };
    }

    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error'
    });
  }
});

// Users endpoint with validation and sanitization
app.get('/users', [
  // Validate and sanitize query parameters
  query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('search').optional().trim().escape().isLength({ max: 50 }).withMessage('Search query too long')
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      status: 'error', 
      errors: errors.array() 
    });
  }

  try {
    // Simulated user data (in real app, this would come from a database)
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter users if search parameter is provided
    if (req.query.search) {
      const search = req.query.search.toLowerCase();
      users = users.filter(user => 
        user.name.toLowerCase().includes(search) || 
        user.email.toLowerCase().includes(search)
      );
    }

    // Pagination
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;

    const results = {};

    if (endIndex < users.length) {
      results.next = {
        page: page + 1,
        limit: limit
      };
    }

    if (startIndex > 0) {
      results.previous = {
        page: page - 1,
        limit: limit
      };
    }

    results.data = users.slice(startIndex, endIndex);
    results.total = users.length;
    results.page = page;
    results.limit = limit;

    res.json(results);
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Failed to retrieve users'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    status: 'error',
    message: `Can't find ${req.originalUrl} on this server!`
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  const statusCode = error.statusCode || 500;
  const message = error.message || 'Internal server error';

  res.status(statusCode).json({
    status: 'error',
    message: message
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

