const express = require('express');
const app = express();

// Security: Set security headers
app.use((req, res, next) => {
  // Security headers
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  // Limit request size
  if (req.method === 'POST' || req.method === 'PUT' || req.method === 'PATCH') {
    const contentLength = req.headers['content-length'];
    if (contentLength && parseInt(contentLength) > 10240) { // 10kb limit
      return res.status(413).json({
        status: 'error',
        message: 'Payload too large'
      });
    }
  }

  next();
});

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Simple rate limiting
const requestCounts = new Map();
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes
const MAX_REQUESTS = 100;

app.use((req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();

  // Clean up old entries
  if (requestCounts.size > 1000) {
    for (const [key, value] of requestCounts) {
      if (now - value.timestamp > RATE_LIMIT_WINDOW) {
        requestCounts.delete(key);
      }
    }
  }

  // Check rate limit
  const record = requestCounts.get(ip) || { count: 0, timestamp: now };

  if (now - record.timestamp > RATE_LIMIT_WINDOW) {
    // Reset counter if outside window
    record.count = 1;
    record.timestamp = now;
  } else {
    // Increment counter
    record.count++;
  }

  requestCounts.set(ip, record);

  if (record.count > MAX_REQUESTS) {
    return res.status(429).json({
      status: 'error',
      message: 'Too many requests, please try again later'
    });
  }

  next();
});

// Input sanitization function
function sanitizeInput(str) {
  if (typeof str !== 'string') return str;

  // Basic XSS protection
  return str
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;');
}

// Sanitize all query parameters
app.use((req, res, next) => {
  if (req.query) {
    for (const key in req.query) {
      if (typeof req.query[key] === 'string') {
        req.query[key] = sanitizeInput(req.query[key]);
      }
    }
  }
  next();
});

// Health check with improved error handling
app.get('/health', (req, res) => {
  try {
    // Validate query parameters
    if (req.query.detailed && req.query.detailed !== 'true' && req.query.detailed !== 'false') {
      return res.status(400).json({ 
        status: 'error',
        message: 'Detailed parameter must be "true" or "false"'
      });
    }

    const healthData = {
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    };

    // Add detailed info if requested
    if (req.query.detailed === 'true') {
      healthData.process = {
        memory: process.memoryUsage(),
        nodeVersion: process.version,
      };
    }

    res.json(healthData);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error'
    });
  }
});

// Users endpoint with validation and sanitization
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    if (req.query.page && (!Number.isInteger(Number(req.query.page)) || Number(req.query.page) < 1)) {
      return res.status(400).json({ 
        status: 'error',
        message: 'Page parameter must be a positive integer'
      });
    }

    if (req.query.limit && (!Number.isInteger(Number(req.query.limit)) || Number(req.query.limit) < 1 || Number(req.query.limit) > 100)) {
      return res.status(400).json({ 
        status: 'error',
        message: 'Limit parameter must be an integer between 1 and 100'
      });
    }

    // Simulated user data
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter users if search parameter is provided
    if (req.query.search) {
      if (req.query.search.length > 50) {
        return res.status(400).json({ 
          status: 'error',
          message: 'Search query too long'
        });
      }

      const search = req.query.search.toLowerCase();
      users = users.filter(user => 
        user.name.toLowerCase().includes(search) || 
        user.email.toLowerCase().includes(search)
      );
    }

    // Pagination
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;
    const startIndex = (page - 1) * limit;
    const endIndex = page * limit;

    const results = {};

    if (endIndex < users.length) {
      results.next = {
        page: page + 1,
        limit: limit
      };
    }

    if (startIndex > 0) {
      results.previous = {
        page: page - 1,
        limit: limit
      };
    }

    results.data = users.slice(startIndex, endIndex);
    results.total = users.length;
    results.page = page;
    results.limit = limit;

    res.json(results);
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Failed to retrieve users'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    status: 'error',
    message: `Can't find ${req.originalUrl} on this server!`
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  const statusCode = res.statusCode !== 200 ? res.statusCode : 500;
  const message = error.message || 'Internal server error';

  res.status(statusCode).json({
    status: 'error',
    message: message
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

