const express = require('express');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet()); // Security headers
app.use(cors()); // CORS protection
app.use(xss()); // XSS protection

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later',
});
app.use('/api', limiter); // Apply to API routes

// Body parsing with size limits
class BadRequestError extends Error {
  constructor(message) {
    super(message);
    this.name = 'BadRequestError';
    this.statusCode = 400;
  }
}

// Input validation middleware
class ValidationError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValidationError';
    this.statusCode = 400;
  }
}

const validateQueryParams = (allowedParams) => {
  return (req, res, next) => {
    const invalidParams = Object.keys(req.query).filter(
      (param) => !allowedParams.includes(param)
    );

    if (invalidParams.length > 0) {
      return next(new ValidationError(`Invalid query parameters: ${invalidParams.join(', ')}`));
    }
    next();
  };
};

// Security: Limit request body size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Health check route
app.get('/health', validateQueryParams(['verbose']), (req, res) => {
  const healthData = {
    status: 'ok',
    timestamp: new Date().toISOString(),
  };

  // Optional verbose information
  if (req.query.verbose === 'true') {
    healthData.info = {
      uptime: process.uptime(),
      nodeVersion: process.version,
    };
  }

  res.json(healthData);
});

// Users route with input validation
app.get('/users', validateQueryParams(['limit', 'offset']), (req, res, next) => {
  try {
    // Validate query parameters if present
    if (req.query.limit !== undefined) {
      const limit = parseInt(req.query.limit);
      if (isNaN(limit) || limit < 1 || limit > 100) {
        return next(new ValidationError('Limit must be a number between 1 and 100'));
      }
    }

    if (req.query.offset !== undefined) {
      const offset = parseInt(req.query.offset);
      if (isNaN(offset) || offset < 0) {
        return next(new ValidationError('Offset must be a non-negative number'));
      }
    }

    // Mock users data
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple pagination
    const limit = req.query.limit ? parseInt(req.query.limit) : mockUsers.length;
    const offset = req.query.offset ? parseInt(req.query.offset) : 0;

    const paginatedUsers = mockUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: mockUsers.length
      }
    });

  } catch (error) {
    next(error);
  }
});

// Error handling middleware
app.use((err, req, res, next) => {
  // Log error (in production, use a logging service)
  console.error('Error:', err);

  // Set default error values
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' && statusCode === 500
    ? 'Internal Server Error'
    : err.message;

  // Security: Don't leak error details in production
  const errorResponse = { message };

  // Include stack only in development
  if (process.env.NODE_ENV === 'development' && statusCode !== 500) {
    errorResponse.stack = err.stack;
  }

  res.status(statusCode).json({
    ...errorResponse,
    success: false
  });
});

// Handle 404
app.use('*', (req, res) => {
  res.status(404).json({
    success: false,
    message: `Route ${req.originalUrl} not found`
  });
});

// Global error handlers
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Rejection:', err);
  // In production: send to logging service and gracefully shutdown
  process.exit(1);
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // In production: send to logging service and gracefully shutdown
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

