{
  "name": "security-demo-app",
  "version": "1.0.0",
  "description": "A simple Express app demonstrating security best practices",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "nodemon app.js"
  },
  "dependencies": {
    "express": "^4.18.0"
  },
  "devDependencies": {
    "helmet": "^7.0.0",
    "express-validator": "^7.0.1",
    "winston": "^3.8.2"
  }
}

/**
 * Improved Express application with security best practices
 * Includes error handling, input validation, and security middleware
 */

const express = require('express');
const helmet = require('helmet');
const { body, validationResult, param } = require('express-validator');
const winston = require('winston');

// Configure logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// If we're not in production, log to the console as well
if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

const app = express();

// Security middleware
app.use(helmet());

// Body parsing with limits to prevent abuse
app.use(express.json({
  limit: '10kb',
  strict: true
}));

// Set timeout to prevent slowloris attacks
app.use((req, res, next) => {
  req.setTimeout(30000); // 30 seconds
  next();
});

// Rate limiting (basic implementation - in production use express-rate-limit)
const requestCounts = new Map();
const RATE_LIMIT_WINDOW_MS = 15 * 60 * 1000; // 15 minutes
const MAX_REQUESTS_PER_WINDOW = 100;

app.use((req, res, next) => {
  const ip = req.ip || req.connection.remoteAddress;
  const now = Date.now();

  // Clean up old entries
  if (requestCounts.size > 1000) {
    for (const [key, value] of requestCounts) {
      if (now - value.timestamp > RATE_LIMIT_WINDOW_MS) {
        requestCounts.delete(key);
      }
    }
  }

  const record = requestCounts.get(ip) || { count: 0, timestamp: now };

  // Reset counter if outside window
  if (now - record.timestamp > RATE_LIMIT_WINDOW_MS) {
    record.count = 0;
    record.timestamp = now;
  }

  record.count++;
  requestCounts.set(ip, record);

  if (record.count > MAX_REQUESTS_PER_WINDOW) {
    logger.warn(`Rate limit exceeded by IP: ${ip}`);
    return res.status(429).json({
      error: 'Too many requests, please try again later.'
    });
  }

  next();
});

// Health check endpoint
app.get('/health', [
  // Input validation - though simple, still validate
  (req, res, next) => {
    // Log the health check request
    logger.info('Health check requested', {
      ip: req.ip,
      method: req.method,
      url: req.url
    });
    next();
  }
], (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      version: '1.0.0'
    });
  } catch (error) {
    logger.error('Error in health check endpoint:', error);
    res.status(500).json({ 
      error: 'Internal server error'
    });
  }
});

// Users endpoint with query parameter validation
app.get('/users', [
  // Validate and sanitize query parameters
  (req, res, next) => {
    // Log the request
    logger.info('Users endpoint accessed', {
      ip: req.ip,
      method: req.method,
      url: req.url,
      query: req.query
    });
    next();
  }
], (req, res) => {
  try {
    // In a real application, these would come from a database
    const mockUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Handle search parameter if provided
    const { search } = req.query;
    let filteredUsers = mockUsers;

    if (search) {
      // Validate search input
      if (typeof search !== 'string') {
        return res.status(400).json({
          error: 'Search parameter must be a string'
        });
      }

      // Sanitize and limit search length
      const searchTerm = search.trim().substring(0, 50);

      if (searchTerm.length > 0) {
        filteredUsers = mockUsers.filter(user => 
          user.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
          user.email.toLowerCase().includes(searchTerm.toLowerCase())
        );
      }
    }

    // Add rate limiting response header
    const ip = req.ip;
    const record = requestCounts.get(ip) || { count: 0, timestamp: Date.now() };
    res.set('X-RateLimit-Remaining', Math.max(0, MAX_REQUESTS_PER_WINDOW - record.count).toString());

    res.json({
      success: true,
      count: filteredUsers.length,
      data: filteredUsers
    });

    logger.info('Users endpoint successful', {
      resultCount: filteredUsers.length,
      search: search || 'none'
    });

  } catch (error) {
    logger.error('Error in users endpoint:', {
      error: error.message,
      stack: error.stack
    });

    res.status(500).json({ 
      error: 'Internal server error'
    });
  }
});

// Error handling middleware
app.use((err, req, res, next) => {
  logger.error('Unhandled error:', {
    error: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  // Don't leak error details in production
  const errorResponse = process.env.NODE_ENV === 'production' 
    ? { error: 'Internal server error' }
    : { error: err.message, stack: err.stack };

  res.status(err.status || 500).json(errorResponse);
});

// 404 handler for unknown routes
app.use('*', (req, res) => {
  logger.warn('404 route not found', {
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  res.status(404).json({
    error: 'Route not found'
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully');
  process.exit(0);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

module.exports = { app, server, logger };

