```javascript
// Improved version of app.js with security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const bodyParser = require('body-parser');

const app = express();

// Security middleware
app.use(helmet({
  // Configure helmet with appropriate settings
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      objectSrc: ["'none'"],
      upgradeInsecureRequests: process.env.NODE_ENV === 'production'
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  frameguard: {
    action: 'deny'
  }
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// CORS configuration
const corsOptions = {
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000', // Restrict origins
  optionsSuccessStatus: 200,
  credentials: true
};
app.use(cors(corsOptions));

// Input size limits and parsing
app.use(bodyParser.json({ limit: '10kb' })); // Limit request size
app.use(bodyParser.urlencoded({ extended: true, limit: '10kb' }));

// Set timeout for requests
app.use((req, res, next) => {
  req.setTimeout(30000); // 30 second timeout
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      version: process.env.npm_package_version || '1.0.0'
    });
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      status: 'error', 
      message: 'Health check failed' 
    });
  }
});

// Users endpoint with error handling
app.get('/users', (req, res) => {
  try {
    // Simulate data access with proper error handling
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Optional: Add pagination or filtering with validation
    const page = parseInt(req.query.page) || 1;
    const limit = parseInt(req.query.limit) || 10;

    // Validate inputs
    if (page < 1 || limit < 1 || limit > 100) {
      return res.status(400).json({
        error: 'Invalid pagination parameters',
        message: 'Page and limit must be positive numbers, limit cannot exceed 100'
      });
    }

    res.json(users);
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Failed to retrieve users' 
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.url} not found`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Uncaught error:', error);

  // Don't expose internal details in production
  const isProd = process.env.NODE_ENV === 'production';
  res.status(error.status || 500).json({
    error: isProd ? 'Internal Server Error' : error.message,
    message: isProd ? 'An error occurred' : error.message
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (error) => {
  console.error('Unhandled Promise Rejection:', error);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  server.close(() => {
    process.exit(1);
  });
});

module.exports = app;
```

### Additional Security Best Practices:

1. **Environment Variables**: Create a `.env` file for configuration:
```env
NODE_ENV=production
PORT=3000
CORS_ORIGIN=http://yourdomain.com
RATE_LIMIT_WINDOW=900000
RATE_LIMIT_MAX=100
```

2. **Add to package.json scripts**:
```json
"scripts": {
  "start": "node app.js",
  "start:prod": "NODE_ENV=production node app.js",
  "dev": "nodemon app.js"
}
```

3. **Use a process manager** like PM2 in production
4. **Implement logging** with a proper logging library
5. **Add input validation** libraries like Joi for complex validation
6. **Set up monitoring** and alerting for your application

These changes will significantly improve the security, reliability, and maintainability of your application.

