const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const winston = require('winston');

// Create Express app
const app = express();

// Configure logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'user-service' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"]
    }
  }
}));

// Limit request body size
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: { error: 'Too many requests from this IP, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Request logging middleware
app.use((req, res, next) => {
  logger.info(`${req.method} ${req.url}`, {
    ip: req.ip,
    userAgent: req.get('User-Agent'),
    timestamp: new Date().toISOString()
  });
  next();
});

// Health check endpoint with input validation
app.get('/health', 
  // Validate query parameters if present
  query('detailed').optional().isBoolean().withMessage('Detailed must be boolean'),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Invalid request parameters',
        details: errors.array() 
      });
    }

    const healthData = {
      status: 'ok', 
      timestamp: new Date().toISOString()
    };

    // Optional detailed response
    if (req.query.detailed === 'true') {
      healthData.service = 'user-service';
      healthData.version = '1.0.0';
    }

    res.json(healthData);
  }
);

// Users endpoint with validation and error handling
app.get('/users', 
  // Input validation for query parameters
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be zero or positive'),
  query('sort').optional().isIn(['name', 'id', 'email']).withMessage('Sort must be name, id, or email'),
  async (req, res) => {
    try {
      // Validate inputs
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: 'Invalid request parameters',
          details: errors.array() 
        });
      }

      // Extract and sanitize query parameters with defaults
      const limit = parseInt(req.query.limit) || 10;
      const offset = parseInt(req.query.offset) || 0;
      const sort = req.query.sort || 'id';

      // Simulated user data
      const mockUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
        { id: 4, name: 'Diana', email: 'diana@example.com' },
        { id: 5, name: 'Evan', email: 'evan@example.com' }
      ];

      // Sort users
      const sortedUsers = [...mockUsers].sort((a, b) => {
        if (a[sort] < b[sort]) return -1;
        if (a[sort] > b[sort]) return 1;
        return 0;
      });

      // Apply pagination
      const paginatedUsers = sortedUsers.slice(offset, offset + limit);

      // Return response with metadata
      res.json({
        data: paginatedUsers,
        meta: {
          total: mockUsers.length,
          limit: limit,
          offset: offset,
          sort: sort
        }
      });
    } catch (error) {
      // Log the actual error for debugging
      logger.error('Error fetching users:', { 
        error: error.message, 
        stack: error.stack,
        timestamp: new Date().toISOString()
      });

      // Return generic error response
      res.status(500).json({ 
        error: 'Internal server error'
      });
    }
  }
);

// 404 handler for undefined routes
app.use('*', (req, res) => {
  logger.warn(`404 - Route not found: ${req.method} ${req.url}`, {
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  res.status(404).json({
    error: 'Route not found'
  });
});

// Global error handling middleware
app.use((error, req, res, next) => {
  logger.error('Unhandled error:', {
    error: error.message,
    stack: error.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Determine status code
  const statusCode = res.statusCode !== 200 ? res.statusCode : 500;

  // Reset status code to prevent sending response twice
  if (!res.headersSent) {
    res.status(statusCode).json({
      error: 'Internal server error'
    });
  }
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Process terminated');
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully');
  server.close(() => {
    logger.info('Process terminated');
  });
});

module.exports = app;

