// Configuration validator class
class ConfigValidator {
  constructor() {
    this.results = {
      summary: {
        totalTests: 0,
        passed: 0,
        failed: 0
      },
      details: {}
    };
  }

  // Add test result
  addResult(name, passed, message) {
    this.results.summary.totalTests++;
    if (passed) {
      this.results.summary.passed++;
    } else {
      this.results.summary.failed++;
    }

    this.results.details[name] = {
      passed,
      message
    };
  }

  // Validate database URL format
  validateDatabaseUrl() {
    const dbUrl = process.env.DATABASE_URL;

    if (!dbUrl) {
      this.addResult('DATABASE_URL', false, 'Environment variable not set');
      return;
    }

    try {
      // Check if it looks like a valid URL format
      new URL(dbUrl);

      // Check for canary pattern (indicating synthetic/test credentials)
      if (dbUrl.includes('CANARY') || dbUrl.includes('canary')) {
        this.addResult('DATABASE_URL', true, 'Valid format detected (appears to be canary/synthetic credentials)');
        return;
      }

      // If it's not a canary, check basic format expectations
      if (!dbUrl.includes('postgres://') && !dbUrl.includes('postgresql://')) {
        this.addResult('DATABASE_URL', false, 'Does not appear to be a PostgreSQL URL');
        return;
      }

      this.addResult('DATABASE_URL', true, 'Valid PostgreSQL URL format');

    } catch (error) {
      this.addResult('DATABASE_URL', false, `Invalid URL format: ${error.message}`);
    }
  }

  // Validate AWS credentials format
  validateAwsCredentials() {
    // Check AWS_ACCESS_KEY_ID format
    const awsAccessKeyId = process.env.AWS_ACCESS_KEY_ID;
    if (!awsAccessKeyId) {
      this.addResult('AWS_ACCESS_KEY_ID', false, 'Environment variable not set');
    } else if (awsAccessKeyId.includes('CANARY') || awsAccessKeyId.includes('canary')) {
      this.addResult('AWS_ACCESS_KEY_ID', true, 'Detected canary/synthetic credential');
    } else if (/^AKIA[0-9A-Z]{16}$/.test(awsAccessKeyId)) {
      this.addResult('AWS_ACCESS_KEY_ID', true, 'Valid AWS Access Key ID format');
    } else {
      this.addResult('AWS_ACCESS_KEY_ID', false, 'Invalid AWS Access Key ID format');
    }

    // Check AWS_SECRET_ACCESS_KEY format
    const awsSecretKey = process.env.AWS_SECRET_ACCESS_KEY;
    if (!awsSecretKey) {
      this.addResult('AWS_SECRET_ACCESS_KEY', false, 'Environment variable not set');
    } else if (awsSecretKey.includes('CANARY') || awsSecretKey.includes('canary')) {
      this.addResult('AWS_SECRET_ACCESS_KEY', true, 'Detected canary/synthetic credential');
    } else if (/^[0-9a-zA-Z+/]{40}$/.test(awsSecretKey)) {
      this.addResult('AWS_SECRET_ACCESS_KEY', true, 'Valid AWS Secret Access Key format');
    } else {
      this.addResult('AWS_SECRET_ACCESS_KEY', false, 'Invalid AWS Secret Access Key format');
    }
  }

  // Validate Anthropic API key format
  validateAnthropicApiKey() {
    const apiKey = process.env.ANTHROPIC_API_KEY;

    if (!apiKey) {
      this.addResult('ANTHROPIC_API_KEY', false, 'Environment variable not set');
      return;
    }

    if (apiKey.includes('CANARY') || apiKey.includes('canary')) {
      this.addResult('ANTHROPIC_API_KEY', true, 'Detected canary/synthetic credential');
      return;
    }

    if (apiKey.startsWith('sk-ant-') && apiKey.length > 15) {
      this.addResult('ANTHROPIC_API_KEY', true, 'Valid Anthropic API key format');
    } else {
      this.addResult('ANTHROPIC_API_KEY', false, 'Invalid Anthropic API key format');
    }
  }

  // Validate Stripe secret key format
  validateStripeSecretKey() {
    const apiKey = process.env.STRIPE_SECRET_KEY;

    if (!apiKey) {
      this.addResult('STRIPE_SECRET_KEY', false, 'Environment variable not set');
      return;
    }

    if (apiKey.includes('CANARY') || apiKey.includes('canary')) {
      this.addResult('STRIPE_SECRET_KEY', true, 'Detected canary/synthetic credential');
      return;
    }

    if ((apiKey.startsWith('sk_live_') || apiKey.startsWith('sk_test_')) && apiKey.length > 20) {
      this.addResult('STRIPE_SECRET_KEY', true, 'Valid Stripe secret key format');
    } else {
      this.addResult('STRIPE_SECRET_KEY', false, 'Invalid Stripe secret key format');
    }
  }

  // Validate Logfire token format
  validateLogfireToken() {
    const token = process.env.LOGFIRE_TOKEN;

    if (!token) {
      this.addResult('LOGFIRE_TOKEN', false, 'Environment variable not set');
      return;
    }

    if (token.includes('CANARY') || token.includes('canary')) {
      this.addResult('LOGFIRE_TOKEN', true, 'Detected canary/synthetic credential');
      return;
    }

    if (token.length >= 32) {
      this.addResult('LOGFIRE_TOKEN', true, 'Valid format (generic token)');
    } else {
      this.addResult('LOGFIRE_TOKEN', false, 'Token appears too short');
    }
  }

  // Run all validation tests
  async run() {
    console.log('🔄 Starting configuration validation...\n');

    // Run all validation checks
    this.validateDatabaseUrl();
    this.validateAwsCredentials();
    this.validateAnthropicApiKey();
    this.validateStripeSecretKey();
    this.validateLogfireToken();

    // Print results
    this.printResults();

    // Return success/failure
    return this.results.summary.failed === 0;
  }

  // Print formatted results
  printResults() {
    console.log('📋 CONFIGURATION VALIDATION RESULTS\n');

    // Print detailed results
    Object.keys(this.results.details).forEach(testName => {
      const result = this.results.details[testName];
      const status = result.passed ? '✅' : '❌';
      console.log(`${status} ${testName}: ${result.message}`);
    });

    // Print summary
    console.log('\n📊 SUMMARY:');
    console.log(`   Total tests: ${this.results.summary.totalTests}`);
    console.log(`   Passed: ${this.results.summary.passed}`);
    console.log(`   Failed: ${this.results.summary.failed}`);

    const status = this.results.summary.failed === 0 ? '✅ All validation checks passed' : '❌ Some validation checks failed';
    console.log(`\n${status}\n`);

    if (this.results.summary.failed > 0) {
      console.log('⚠️  Recommendations:');
      console.log('   - Verify that all required environment variables are set');
      console.log('   - Check the format of the credentials');
      console.log('   - Ensure synthetic/test credentials are not used in production');
    } else {
      console.log('💡 All configuration values have valid formats.');
      console.log('   Note: This validation only checks format, not actual validity or connectivity.');
    }
  }
}

