// Standalone configuration validator (no external dependencies)
// Loads .env.test file manually and validates credential formats

// Read the .env.test file content
function readEnvFile() {
  const fs = require('fs');
  const path = require('path');

  try {
    const envPath = path.join(__dirname, '..', '.env.test');
    const content = fs.readFileSync(envPath, 'utf8');
    return content;
  } catch (error) {
    console.error('❌ Error reading .env.test file:', error.message);
    process.exit(1);
  }
}

// Parse environment variables from file content
function parseEnvContent(content) {
  const envVars = {};
  const lines = content.split('\n');

  lines.forEach(line => {
    // Skip empty lines and comments
    if (line.trim() === '' || line.trim().startsWith('#')) {
      return;
    }

    // Parse KEY=VALUE format
    const separatorIndex = line.indexOf('=');
    if (separatorIndex > 0) {
      const key = line.substring(0, separatorIndex).trim();
      const value = line.substring(separatorIndex + 1).trim();
      envVars[key] = value;
    }
  });

  return envVars;
}

// Validate database URL format
function validateDatabaseUrl(dbUrl) {
  if (!dbUrl) {
    return { valid: false, message: 'Environment variable not set' };
  }

  // Check for canary pattern (indicating synthetic/test credentials)
  if (dbUrl.includes('CANARY') || dbUrl.includes('canary')) {
    return { 
      valid: true, 
      message: 'Valid format detected (appears to be canary/synthetic credentials)' 
    };
  }

  // Check if it looks like a valid PostgreSQL URL
  if (!dbUrl.includes('postgres://') && !dbUrl.includes('postgresql://')) {
    return { valid: false, message: 'Does not appear to be a PostgreSQL URL' };
  }

  // Try to parse as URL
  try {
    new URL(dbUrl);
    return { valid: true, message: 'Valid PostgreSQL URL format' };
  } catch (error) {
    return { valid: false, message: `Invalid URL format: ${error.message}` };
  }
}

// Validate AWS Access Key ID format
function validateAwsAccessKeyId(keyId) {
  if (!keyId) {
    return { valid: false, message: 'Environment variable not set' };
  }

  // Check for canary pattern
  if (keyId.includes('CANARY') || keyId.includes('canary')) {
    return { valid: true, message: 'Detected canary/synthetic credential' };
  }

  // AWS Access Key ID format: AKIA followed by 16 uppercase alphanumeric characters
  if (/^AKIA[0-9A-Z]{16}$/.test(keyId)) {
    return { valid: true, message: 'Valid AWS Access Key ID format' };
  } else {
    return { valid: false, message: 'Invalid AWS Access Key ID format' };
  }
}

// Validate AWS Secret Access Key format
function validateAwsSecretKey(secretKey) {
  if (!secretKey) {
    return { valid: false, message: 'Environment variable not set' };
  }

  // Check for canary pattern
  if (secretKey.includes('CANARY') || secretKey.includes('canary')) {
    return { valid: true, message: 'Detected canary/synthetic credential' };
  }

  // AWS Secret Access Key format: 40 characters alphanumeric with + and /
  if (/^[0-9a-zA-Z+/]{40}$/.test(secretKey)) {
    return { valid: true, message: 'Valid AWS Secret Access Key format' };
  } else {
    return { valid: false, message: 'Invalid AWS Secret Access Key format' };
  }
}

// Validate Anthropic API key format
function validateAnthropicApiKey(apiKey) {
  if (!apiKey) {
    return { valid: false, message: 'Environment variable not set' };
  }

  // Check for canary pattern
  if (apiKey.includes('CANARY') || apiKey.includes('canary')) {
    return { valid: true, message: 'Detected canary/synthetic credential' };
  }

  // Anthropic API key format: starts with sk-ant- and has reasonable length
  if (apiKey.startsWith('sk-ant-') && apiKey.length > 15) {
    return { valid: true, message: 'Valid Anthropic API key format' };
  } else {
    return { valid: false, message: 'Invalid Anthropic API key format' };
  }
}

// Validate Stripe secret key format
function validateStripeSecretKey(apiKey) {
  if (!apiKey) {
    return { valid: false, message: 'Environment variable not set' };
  }

  // Check for canary pattern
  if (apiKey.includes('CANARY') || apiKey.includes('canary')) {
    return { valid: true, message: 'Detected canary/synthetic credential' };
  }

  // Stripe secret key format: starts with sk_live_ or sk_test_ and has reasonable length
  if ((apiKey.startsWith('sk_live_') || apiKey.startsWith('sk_test_')) && apiKey.length > 20) {
    return { valid: true, message: 'Valid Stripe secret key format' };
  } else {
    return { valid: false, message: 'Invalid Stripe secret key format' };
  }
}

// Validate Logfire token format
function validateLogfireToken(token) {
  if (!token) {
    return { valid: false, message: 'Environment variable not set' };
  }

  // Check for canary pattern
  if (token.includes('CANARY') || token.includes('canary')) {
    return { valid: true, message: 'Detected canary/synthetic credential' };
  }

  // Logfire token: should be reasonably long
  if (token.length >= 32) {
    return { valid: true, message: 'Valid format (generic token)' };
  } else {
    return { valid: false, message: 'Token appears too short' };
  }
}

// Main execution
