  console.log('🔄 Starting configuration validation...\n');

  // Read and parse .env.test file
  const fileContent = readEnvFile();
  const envVars = parseEnvContent(fileContent);

  // Track results
  const results = {
    summary: {
      totalTests: 0,
      passed: 0,
      failed: 0
    },
