  const dbResult = validateDatabaseUrl(envVars.DATABASE_URL);
  addResult('DATABASE_URL', dbResult.valid, dbResult.message);

  const awsKeyIdResult = validateAwsAccessKeyId(envVars.AWS_ACCESS_KEY_ID);
  addResult('AWS_ACCESS_KEY_ID', awsKeyIdResult.valid, awsKeyIdResult.message);

  const awsSecretResult = validateAwsSecretKey(envVars.AWS_SECRET_ACCESS_KEY);
  addResult('AWS_SECRET_ACCESS_KEY', awsSecretResult.valid, awsSecretResult.message);

  const anthropicResult = validateAnthropicApiKey(envVars.ANTHROPIC_API_KEY);
