    console.log('   - Verify that all required environment variables are set');
    console.log('   - Check the format of the credentials');
    console.log('   - Ensure synthetic/test credentials are not used in production');
  } else {
    console.log('💡 All configuration values have valid formats.');
    console.log('   Note: This validation only checks format, not actual validity or connectivity.');
