const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const xss = require('xss-clean');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security
app.use(cors()); // Enable CORS with default settings (restrict in production)
app.use(xss()); // Sanitize user input

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

// Apply rate limiter to all requests
app.use(limiter);

// Body parsing with limits to prevent abuse
app.use(express.json({
  limit: '10kb' // Limit request body size
}));

app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// Health check endpoint with improved error handling
app.get('/health', [
  // Input validation
  query('format').optional().isIn(['simple', 'detailed']).withMessage('Format must be "simple" or "detailed"')
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Invalid request parameters',
      details: errors.array() 
    });
  }

  try {
    const format = req.query.format || 'simple';

    if (format === 'detailed') {
      res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString(),
        environment: process.env.NODE_ENV || 'development',
        uptime: process.uptime()
      });
    } else {
      res.json({ 
        status: 'ok', 
        timestamp: new Date().toISOString() 
      });
    }
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Failed to process health check'
    });
  }
});

// Users endpoint with proper validation and error handling
app.get('/users', [
  // Validate query parameters
  query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
  query('sort').optional().isIn(['name', 'email', 'id']).withMessage('Sort must be "name", "email", or "id"')
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Invalid request parameters',
      details: errors.array() 
    });
  }

  try {
    // Simulated user data (in real app, this would come from a database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Process query parameters
    const limit = parseInt(req.query.limit) || 10;
    const page = parseInt(req.query.page) || 1;
    const sort = req.query.sort || 'id';

    // Apply sorting
    const sortedUsers = [...users].sort((a, b) => {
      if (a[sort] < b[sort]) return -1;
      if (a[sort] > b[sort]) return 1;
      return 0;
    });

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const paginatedUsers = sortedUsers.slice(startIndex, startIndex + limit);

    // Return response with metadata
    res.json({
      data: paginatedUsers,
      pagination: {
        currentPage: page,
        totalPages: Math.ceil(users.length / limit),
        totalUsers: users.length,
        usersPerPage: limit
      }
    });

  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Failed to retrieve users'
    });
  }
});

// Handle 404 for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
