      origin: false // disabled by default
    }
  }
};

module.exports = config;

// Input validation middleware
const createError = require('http-errors');

/**
 * Basic input sanitization
 */
const sanitizeInput = (req, res, next) => {
  const sanitizeObject = (obj) => {
    if (typeof obj !== 'object' || obj === null) return obj;

    const sanitized = {};
    for (const [key, value] of Object.entries(obj)) {
      // Remove potential prototype pollution vectors
      if (key === '__proto__' || key === 'constructor' || key === 'prototype') {
        continue;
      }

      if (typeof value === 'string') {
        // Basic XSS prevention - trim and limit length
        sanitized[key] = value.trim().substring(0, 1000);
      } else if (typeof value === 'object' && value !== null) {
        sanitized[key] = sanitizeObject(value);
      } else {
        sanitized[key] = value;
      }
    }
    return sanitized;
  };

  // Sanitize query, params, and body
  if (req.query) req.query = sanitizeObject(req.query);
  if (req.params) req.params = sanitizeObject(req.params);
  if (req.body) req.body = sanitizeObject(req.body);

  next();
};

/**
 * Validate user ID parameter
 */
const validateUserId = (req, res, next) => {
  const { id } = req.params;

  // Check if ID is provided
  if (!id) {
    return next(createError(400, 'User ID is required'));
  }

  // Check if ID is a positive integer
  const userId = parseInt(id, 10);
  if (isNaN(userId) || userId <= 0 || !Number.isInteger(userId)) {
    return next(createError(400, 'Invalid user ID format'));
  }

  // Attach validated ID to request
  req.userId = userId;
  next();
};

module.exports = {
  sanitizeInput,
  validateUserId
};

