/**
 * Central error handling middleware
 * Should be placed at the end of the middleware stack
 */
const errorHandler = (err, req, res, next) => {
  // Set default error status and message
  const status = err.status || 500;
  let message = status === 500 ? 'Internal Server Error' : err.message;

  // Don't leak stack traces and sensitive info in production
  if (process.env.NODE_ENV === 'production') {
    console.error(`[${new Date().toISOString()}] ${req.method} ${req.url} - Status: ${status} - Error: ${err.message}`);

    // For server errors, don't expose internal details
    if (status === 500) {
      message = 'Internal Server Error';
    }
  } else {
    // In development, include stack trace
    console.error(err);
  }

  // Return error response in consistent format
  res.status(status).json({
    error: {
      message,
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
      timestamp: new Date().toISOString(),
      path: req.url
    }
  });
};

