  if (req.method === 'POST' || req.method === 'PUT' || req.method === 'PATCH') {
    let body = '';
    req.on('data', chunk => {
      if (body.length > 10240) { // 10KB limit
        req.destroy(); // Close connection if body is too large
      }
      body += chunk;
    });

    req.on('end', () => {
      if (body.length > 0) {
        try {
          req.body = JSON.parse(body);
        } catch (e) {
          // Invalid JSON
        }
      }
      next();
    });

    req.on('error', () => {
      res.status(400).json({
        error: 'Invalid request body',
        timestamp: new Date().toISOString()
      });
    });
  } else {
    next();
  }
});

// Rate limiting with a simple in-memory store
const requestCounts = new Map();
const RATE_LIMIT_WINDOW = 15 * 60 * 1000; // 15 minutes
const RATE_LIMIT_MAX = 100; // 100 requests per window

app.use((req, res, next) => {
  const ip = req.ip || 'unknown';
  const now = Date.now();
  const windowStart = now - RATE_LIMIT_WINDOW;

  // Clean up old entries
  if (requestCounts.has(ip)) {
    const requestTimes = requestCounts.get(ip).filter(time => time > windowStart);
    requestCounts.set(ip, requestTimes);
  } else {
    requestCounts.set(ip, []);
  }

  // Check if rate limit exceeded
  if (requestCounts.get(ip).length >= RATE_LIMIT_MAX) {
    return res.status(429).json({
      error: 'Too many requests from this IP, please try again later.',
      timestamp: new Date().toISOString()
    });
  }

  // Add current request time
  requestCounts.get(ip).push(now);
  next();
});

