const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// Security middleware
app.use(helmet()); // Sets various HTTP headers for security

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false, // Disable the X-RateLimit-* headers
});

app.use(limiter);

// CORS configuration - be specific about allowed origins in production
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS || '*', // Configure with specific domains in production
  credentials: true,
}));

// Body parsing with size limits to prevent abuse
app.use(express.json({
  limit: '10kb', // Limit request body size
  strict: true, // Only parse arrays and objects
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb',
}));

// Input validation middleware for user ID parameter
const validateUserId = (req, res, next) => {
  const { id } = req.params;

  // Validate that ID is a positive integer
  if (id && (!Number.isInteger(Number(id)) || Number(id) <= 0)) {
    return res.status(400).json({
      error: 'Invalid user ID. ID must be a positive integer.',
    });
  }

  next();
};

// Secure health check endpoint
app.get('/health', (req, res) => {
  // Add some basic validation for query parameters if present
  if (req.query && Object.keys(req.query).length > 5) {
    return res.status(400).json({
      error: 'Too many query parameters',
    });
  }

  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString() 
  });
});

// Users endpoint with proper error handling
app.get('/users', (req, res) => {
  try {
    // Validate query parameters
    const validParams = ['limit', 'offset', 'sort'];
    const invalidParams = Object.keys(req.query).filter(param => !validParams.includes(param));

    if (invalidParams.length > 0) {
      return res.status(400).json({
        error: `Invalid query parameters: ${invalidParams.join(', ')}`,
        validParams: validParams
      });
    }

    // Process valid parameters
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply limit if provided
    if (req.query.limit) {
      const limit = parseInt(req.query.limit, 10);
      if (isNaN(limit) || limit < 1 || limit > 100) {
        return res.status(400).json({
          error: 'Limit must be a number between 1 and 100'
        });
      }
      users = users.slice(0, limit);
    }

    res.json(users);
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({
      error: 'Internal server error'
    });
  }
});

// 404 handler for undefined routes
app.use('*', (req, res) => {
  res.status(404).json({
    error: `Route ${req.method} ${req.url} not found`
  });
});

// Global error handler
app.use((error, req, res, next) => {
  console.error('Unhandled error:', error);

  // Don't leak error details in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(500).json({
    error: isProduction ? 'Internal server error' : error.message
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Ensure the app is exported for testing
module.exports = app;
module.exports.server = server;

