// validate-credentials.js
// Script to validate environment credentials
// Note: This will only check format and attempt non-intrusive validation

require('dotenv').config({ path: '.env.test' });

const https = require('https');
const { Client } = require('pg');

// Function to check if a URL is reachable
function checkUrl(url, timeout = 5000) {
  return new Promise((resolve) => {
    try {
      // Parse the URL
      const urlObj = new URL(url);

      const options = {
        hostname: urlObj.hostname,
        port: urlObj.port || (urlObj.protocol === 'https:' ? 443 : 80),
        path: urlObj.pathname + urlObj.search,
        method: 'GET',
        timeout: timeout,
        // Don't send any authentication by default
      };

      // For health checks, we'll use known health check endpoints
      // or safe endpoints that don't consume resources

      const req = https.request(options, (res) => {
        resolve({
          success: true,
          statusCode: res.statusCode,
          message: `Connection successful: ${res.statusCode}`
        });
      });

      req.on('error', (error) => {
        resolve({
          success: false,
          message: `Request error: ${error.message}`
        });
      });

      req.on('timeout', () => {
        req.destroy();
        resolve({
          success: false,
          message: 'Request timeout'
        });
      });

      req.end();
    } catch (error) {
      resolve({
        success: false,
        message: `URL parsing error: ${error.message}`
      });
    }
  });
}

// Function to test PostgreSQL connection
async function testDatabaseConnection() {
  const databaseUrl = process.env.DATABASE_URL;

  if (!databaseUrl) {
    return { success: false, message: 'DATABASE_URL not found in environment' };
  }

  // Check if it looks like a valid PostgreSQL URL
  if (!databaseUrl.includes('postgres://') && !databaseUrl.includes('postgresql://')) {
    return { success: false, message: 'Invalid PostgreSQL URL format' };
  }

  const client = new Client({ connectionString: databaseUrl });

  try {
    await client.connect();
    // Instead of running a heavy query, run a lightweight one
    const result = await client.query('SELECT 1 as test');
    await client.end();

    return { 
      success: true, 
      message: 'Database connection successful',
      data: result.rows[0]
    };
  } catch (error) {
    // Always close the client on error
    try {
      await client.end();
    } catch (e) {
      // Ignore cleanup errors
    }

    return { 
      success: false, 
      message: `Database connection failed: ${error.message}` 
    };
  }
}

// Function to test API keys with non-intrusive requests
async function testApiKey(serviceName, apiKey, testConfig) {
  if (!apiKey) {
    return { success: false, message: `${serviceName} key not found` };
  }

  // Check if key has "CANARY" in it, which suggests it's not real
  if (apiKey.includes('CANARY')) {
    return { 
      success: false, 
      message: `${serviceName} key appears to be a synthetic test credential (contains 'CANARY')` 
    };
  }

  const { url, headers, successCheck } = testConfig;

  return new Promise((resolve) => {
    try {
      const urlObj = new URL(url);

      const options = {
        hostname: urlObj.hostname,
        port: urlObj.port || (urlObj.protocol === 'https:' ? 443 : 80),
        path: urlObj.pathname + urlObj.search,
        method: 'GET',
        timeout: 10000,
        headers: {
          ...headers,
          'User-Agent': 'credential-validator/1.0'
        }
      };

      const req = https.request(options, (res) => {
        let data = '';

        res.on('data', (chunk) => {
          data += chunk;
        });

        res.on('end', () => {
          try {
            const parsed = JSON.parse(data);
            if (successCheck(res, parsed)) {
              resolve({
                success: true,
                message: `${serviceName} API key valid`,
                statusCode: res.statusCode
              });
            } else {
              resolve({
                success: false,
                message: `${serviceName} API key invalid or unauthorized`,
                statusCode: res.statusCode,
                response: parsed
              });
            }
          } catch (e) {
            // If response isn't JSON, check status code
            if (res.statusCode >= 200 && res.statusCode < 300) {
              resolve({
                success: true,
                message: `${serviceName} API key valid (non-JSON response)`,
                statusCode: res.statusCode
              });
            } else {
              resolve({
                success: false,
                message: `${serviceName} API request failed`,
                statusCode: res.statusCode
              });
            }
          }
        });
      });

      req.on('error', (error) => {
        resolve({
          success: false,
          message: `Request error: ${error.message}`
        });
      });

      req.on('timeout', () => {
        req.destroy();
        resolve({
          success: false,
          message: 'Request timeout'
        });
      });

      req.end();
    } catch (error) {
      resolve({
        success: false,
        message: `Setup error: ${error.message}`
      });
    }
  });
}

// Main execution
async function main() {
  console.log('Validating credentials from .env.test...\n');

  // Test database connection
  console.log('1. Testing Database Connection:');
  const dbResult = await testDatabaseConnection();
  console.log(dbResult);
  console.log('');

  // Test AWS credentials (we'll just check format since actual validation requires AWS SDK)
  console.log('2. Testing AWS Credentials:');
  const awsKey = process.env.AWS_ACCESS_KEY_ID;
  const awsSecret = process.env.AWS_SECRET_ACCESS_KEY;

  if (!awsKey) {
    console.log({ success: false, message: 'AWS_ACCESS_KEY_ID not found' });
  } else if (awsKey.includes('CANARY')) {
    console.log({ 
      success: false, 
      message: 'AWS key appears to be a synthetic test credential (contains 'CANARY')' 
    });
  } else {
    // Basic format validation for AWS keys
    const validFormat = awsKey.startsWith('AKIA') && awsKey.length === 20;
    console.log({
      success: validFormat,
      message: validFormat ? 'AWS key has valid format' : 'AWS key has invalid format',
      keyPreview: awsKey.substring(0, 5) + '...'
    });
  }

  if (!awsSecret) {
    console.log({ success: false, message: 'AWS_SECRET_ACCESS_KEY not found' });
  } else if (awsSecret.includes('CANARY')) {
    console.log({ 
      success: false, 
      message: 'AWS secret appears to be a synthetic test credential (contains 'CANARY')' 
    });
  } else {
    console.log({
      success: true,
      message: 'AWS secret key format appears valid',
      keyPreview: awsSecret.substring(0, 5) + '...'
    });
  }

  console.log('');

  // Test Anthropic API key
  console.log('3. Testing Anthropic API Key:');
  const anthropicResult = await testApiKey(
    'Anthropic', 
    process.env.ANTHROPIC_API_KEY, 
    {
      url: 'https://api.anthropic.com/v1/complete',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': process.env.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01'
      },
      successCheck: (res, data) => res.statusCode === 400 // 400 means we reached the API but had a bad request (key was accepted)
    }
  );
  console.log(anthropicResult);
  console.log('');

  // Test Stripe API key
  console.log('4. Testing Stripe API Key:');
  const stripeResult = await testApiKey(
    'Stripe', 
    process.env.STRIPE_SECRET_KEY, 
    {
      url: 'https://api.stripe.com/v1/account',
      headers: {
        'Authorization': `Bearer ${process.env.STRIPE_SECRET_KEY}`
      },
      successCheck: (res, data) => res.statusCode === 200
    }
  );
  console.log(stripeResult);
  console.log('');

  // Test Logfire token
  console.log('5. Testing Logfire Token:');
  // Logfire uses Auto-Instrumentation API
  const logfireResult = await testApiKey(
    'Logfire', 
    process.env.LOGFIRE_TOKEN, 
    {
      url: 'https://logfire.shuttleapp.rs/api/health',
      headers: {
        'Authorization': `Bearer ${process.env.LOGFIRE_TOKEN}`
      },
      successCheck: (res, data) => res.statusCode === 200 || res.statusCode === 401
    }
  );
  console.log(logfireResult);
  console.log('');

  // Summary
  console.log('=== SUMMARY ===');
  const tests = [dbResult, anthropicResult, stripeResult, logfireResult];
  const successful = tests.filter(t => t.success).length;
  console.log(`\n${successful}/${tests.length} API tests successful`);

  // Note about AWS (we didn't make a real API call)
  console.log('\nNote: AWS credentials were only format-validated, not tested against AWS API');
}

// Handle unhandled errors
process.on('unhandledRejection', (err) => {
  console.error('Unhandled rejection:', err);
  process.exit(1);
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught exception:', err);
  process.exit(1);
});

// Run the validation if this file is executed directly
if (require.main === module) {
  main().catch(err => {
    console.error('Unexpected error:', err);
    process.exit(1);
  });
}

// Export for testing
module.exports = { testDatabaseConnection, testApiKey };

